/* Icelandic Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jon": "God is gracious — Hebrew Yohanan", "Gudrun": "god's secret lore — Old Norse gud + run", "Sigurdur": "victory guardian — Old Norse sigr + vordr", "Anna": "grace — Hebrew Hannah", "Einar": "one warrior — Old Norse ein + arr", "Bjork": "birch — Icelandic", "Jonsson": "Not a surname but a true patronymic, renewed each generation.", "Jonsdottir": "The feminine patronymic form.", "Gudmundsson": "A classic patronymic.", "Einarsdottir": "A classic feminine patronymic."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jon';
console.log(lookup(q));

